const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;
const DefaultPrng = std.rand.DefaultPrng;

pub const Vocab = struct {
    tokens: [][]const u8,

    pub fn init(tokens_in: [][]const u8) Vocab {
        return .{ .tokens = tokens_in };
    }
};

const NoiseProfile = enum { marrakesh };

pub const QuantumAPI = struct {
    allocator: Allocator,
    crn: []const u8,
    prng: DefaultPrng,

    pub fn init(allocator: Allocator, crn: []const u8, seed: u64) !QuantumAPI {
        return .{
            .allocator = allocator,
            .crn = crn,
            .prng = DefaultPrng.init(seed),
        };
    }

    pub fn deinit(self: *QuantumAPI) void {}

    pub fn getNoise(self: *QuantumAPI, n: usize, profile: NoiseProfile) ![]f64 {
        _ = profile;
        var buf = try self.allocator.alloc(f64, n);
        var r = self.prng.random();
        var i: usize = 0;
        while (i < n) : (i += 1) {
            buf[i] = r.floatNorm(f64);
        }
        return buf;
    }
};

pub const AstroEmbed = struct {
    allocator: Allocator,
    knots: [7]f64,

    pub fn init(allocator: Allocator, knots: [7]f64) !AstroEmbed {
        return .{ .allocator = allocator, .knots = knots };
    }

    pub fn deinit(self: *AstroEmbed) void {}

    fn bsplineBasisRecursive(x: f64, i: usize, k: usize, knots: []const f64) f64 {
        if (k == 0) {
            if (x >= knots[i] and x < knots[i + 1]) return 1.0 else return 0.0;
        } else {
            const denom1 = knots[i + k] - knots[i];
            const denom2 = knots[i + k + 1] - knots[i + 1];
            const term1 = if (denom1 != 0.0) ((x - knots[i]) / denom1) * bsplineBasisRecursive(x, i, k - 1, knots) else 0.0;
            const term2 = if (denom2 != 0.0) ((knots[i + k + 1] - x) / denom2) * bsplineBasisRecursive(x, i + 1, k - 1, knots) else 0.0;
            return term1 + term2;
        }
        return 0.0;
    }

    pub fn bSplineBasis(self: *AstroEmbed, x_in: f64, i: usize, k: usize) f64 {
        _ = self;
        const n: usize = 6;
        const p = k;
        var t: [11]f64 = undefined;
        var j: usize = 0;
        while (j < p + 1) : (j += 1) t[j] = 0.0;
        j = p + 1;
        while (j <= n) : (j += 1) {
            t[j] = @as(f64, @floatFromInt(j - p)) / @as(f64, @floatFromInt(n - p + 1));
        }
        j = n + 1;
        while (j < n + p + 2) : (j += 1) t[j] = 1.0;
        var x = x_in;
        if (x < 0.0) x = 0.0;
        if (x >= 1.0) x = 0.999999999;
        return bsplineBasisRecursive(x, i, p, t[0..]);
    }

    pub fn lorenzPhase(self: *AstroEmbed, x: f64, t: f64) f64 {
        _ = self;
        return math.sin(x * 0.013021 + t * 0.020743) * math.pi;
    }

    pub fn normalizeEmbeds(self: *AstroEmbed, v: *f64) void {
        _ = self;
        const a = @abs(*v);
        if (a > 1.0) *v = *v / a;
    }
};

pub const PAdicTokenizer = struct {
    vocab_size: usize,
    padic_base: usize,
    max_depth: usize,
    bits_per_digit: u6,
    bit_mask: u32,
    astro_knots: [7]f64,
    quantum_crn: []const u8,
    seed: u64,
    allocator: Allocator,
    vocab: Vocab,

    pub fn init(allocator: Allocator, vocab: Vocab, base: usize, depth: usize) !PAdicTokenizer {
        if (base < 2) return error.InvalidBase;
        if (depth == 0) return error.InvalidDepth;
        const bpd_u32 = math.log2_int_ceil(u32, @as(u32, @intCast(base)));
        if (@as(usize, @intCast(bpd_u32)) * depth > 32) return error.InvalidDepth;
        return PAdicTokenizer{
            .vocab_size = vocab.tokens.len,
            .padic_base = base,
            .max_depth = depth,
            .bits_per_digit = @as(u6, @intCast(bpd_u32)),
            .bit_mask = (@as(u32, 1) << @as(u5, @intCast(bpd_u32))) - 1,
            .astro_knots = [_]f64{ 0.0, 0.25, 0.5, 0.75, 1.0, 1.25, 1.5 },
            .quantum_crn = "crn:v1:bluemix:public:quantum-computing:us-east:a/3739b57074604d31a8042e8955ee8cc3:646a80b5-12f7-44e8-b8a0-d8c810073bd2::[1]",
            .seed = 42,
            .allocator = allocator,
            .vocab = vocab,
        };
    }

    pub fn deinit(self: *PAdicTokenizer) void {
        _ = self;
    }

    pub fn encode(self: *PAdicTokenizer, text: []const u8) ![]u32 {
        var tokens = try self.allocator.alloc(u32, text.len);
        errdefer self.allocator.free(tokens);
        for (text, 0..) |ch, i| {
            const ord = @as(u32, @intCast(ch));
            tokens[i] = self.padicEncode(ord);
        }
        return tokens;
    }

    pub fn decode(self: *PAdicTokenizer, tokens: []const u32) ![]u8 {
        var chars = try self.allocator.alloc(u8, tokens.len);
        errdefer self.allocator.free(chars);
        for (tokens, 0..) |tok, i| {
            const ord = self.padicDecode(tok);
            chars[i] = @as(u8, @truncate(ord));
        }
        return chars;
    }

    fn padicEncode(self: *const PAdicTokenizer, n: u32) u32 {
        var result: u32 = 0;
        var mut_n = n;
        var shift: u6 = 0;
        var i: usize = 0;
        const base_u32: u32 = @as(u32, @intCast(self.padic_base));
        while (i < self.max_depth) : (i += 1) {
            const digit: u32 = mut_n % base_u32;
            result |= (digit << shift);
            mut_n /= base_u32;
            shift += self.bits_per_digit;
            if (mut_n == 0) break;
        }
        return result;
    }

    fn padicDecode(self: *const PAdicTokenizer, encoded: u32) u32 {
        var result: u32 = 0;
        var mut_enc: u32 = encoded;
        var i: usize = 0;
        var place: u32 = 1;
        const base_u32: u32 = @as(u32, @intCast(self.padic_base));
        while (i < self.max_depth) : (i += 1) {
            const digit: u32 = mut_enc & self.bit_mask;
            result += digit * place;
            mut_enc >>= self.bits_per_digit;
            place *= base_u32;
            if (mut_enc == 0) break;
        }
        return result % @as(u32, @intCast(self.vocab_size));
    }

    pub fn embedTokens(self: *PAdicTokenizer, tokens: []const u32, allocator: Allocator) ![]f64 {
        const dim = 7;
        var embeds = try allocator.alloc(f64, tokens.len * dim);
        errdefer allocator.free(embeds);
        var qapi = try QuantumAPI.init(allocator, self.quantum_crn, self.seed);
        defer qapi.deinit();
        var ast = try AstroEmbed.init(allocator, self.astro_knots);
        defer ast.deinit();
        var qnoise = try qapi.getNoise(tokens.len * dim, .marrakesh);
        defer allocator.free(qnoise);
        for (tokens, 0..) |tok, ti| {
            for (0..dim) |d| {
                const phase = ast.lorenzPhase(@as(f64, @floatFromInt(tok)), @as(f64, @floatFromInt(ti + d)));
                const ratio = @as(f64, @floatFromInt(tok % @as(u32, @intCast(self.vocab_size)))) / @as(f64, @floatFromInt(self.vocab_size));
                const spline = ast.bSplineBasis(ratio, d, 3);
                var embed = spline * math.cos(phase) * self.astro_knots[d];
                embed += qnoise[(ti * dim + d) % qnoise.len] * 0.01;
                ast.normalizeEmbeds(&embed);
                embeds[ti * dim + d] = embed;
            }
        }
        return embeds;
    }

    pub fn decodeFromEmbeds(self: *PAdicTokenizer, embeds: []const f64, vocab: *Vocab, allocator: Allocator) ![]u8 {
        _ = self;
        const dim: usize = 7;
        if (embeds.len % dim != 0) return error.InvalidEmbeds;
        var output = try allocator.alloc(u8, embeds.len / dim);
        errdefer allocator.free(output);
        const vlen = vocab.tokens.len;
        if (vlen == 0) return error.EmptyVocab;
        var i: usize = 0;
        while (i < embeds.len / dim) : (i += 1) {
            var sum: f64 = 0.0;
            var d: usize = 0;
            while (d < dim) : (d += 1) sum += embeds[i * dim + d];
            const avg = sum / @as(f64, @floatFromInt(dim));
            const val = (math.tanh(avg) + 1.0) * 0.5;
            var idx = @as(isize, @intFromFloat(val * @as(f64, @floatFromInt(vlen))));
            if (idx < 0) idx = 0;
            if (idx >= @as(isize, @intCast(vlen))) idx = @as(isize, @intCast(vlen - 1));
            const tok_slice = vocab.tokens[@as(usize, @intCast(idx))];
            output[i] = if (tok_slice.len > 0) tok_slice[0] else 0;
        }
        return output;
    }

    fn padicDecompose(self: *const PAdicTokenizer, encoded: u32) [7]u8 {
        var rep: [7]u8 = [_]u8{0} ** 7;
        var mut = encoded;
        var d: usize = 0;
        while (d < self.max_depth and d < 7) : (d += 1) {
            rep[d] = @as(u8, @truncate(mut & self.bit_mask));
            mut >>= self.bits_per_digit;
            if (mut == 0) break;
        }
        return rep;
    }

    pub fn batchEncode(self: *PAdicTokenizer, texts: [][]const u8, allocator: Allocator) ![][]u32 {
        var batches = try allocator.alloc([]u32, texts.len);
        var filled: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < filled) : (j += 1) allocator.free(batches[j]);
            allocator.free(batches);
        }
        for (texts, 0..) |text, i| {
            batches[i] = try self.encode(text);
            filled += 1;
        }
        return batches;
    }

    pub fn batchDecode(self: *PAdicTokenizer, tokenss: [][]const u32, allocator: Allocator) ![][]u8 {
        var decodes = try allocator.alloc([]u8, tokenss.len);
        var filled: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < filled) : (j += 1) allocator.free(decodes[j]);
            allocator.free(decodes);
        }
        for (tokenss, 0..) |tokens, i| {
            decodes[i] = try self.decode(tokens);
            filled += 1;
        }
        return decodes;
    }

    pub fn getVocabSize(self: *const PAdicTokenizer) usize {
        return self.vocab_size;
    }

    pub fn encodeBatchToEmbeds(self: *PAdicTokenizer, texts: [][]const u8, allocator: Allocator) ![][]f64 {
        var embeds_list = try allocator.alloc([]f64, texts.len);
        var filled: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < filled) : (j += 1) allocator.free(embeds_list[j]);
            allocator.free(embeds_list);
        }
        for (texts, 0..) |text, i| {
            const tokens = try self.encode(text);
            defer allocator.free(tokens);
            embeds_list[i] = try self.embedTokens(tokens, allocator);
            filled += 1;
        }
        return embeds_list;
    }

    pub fn decodeBatchFromEmbeds(self: *PAdicTokenizer, embeds_list: [][]const f64, vocab: *Vocab, allocator: Allocator) ![][]u8 {
        var decodes = try allocator.alloc([]u8, embeds_list.len);
        var filled: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < filled) : (j += 1) allocator.free(decodes[j]);
            allocator.free(decodes);
        }
        for (embeds_list, 0..) |embeds, i| {
            decodes[i] = try self.decodeFromEmbeds(embeds, vocab, allocator);
            filled += 1;
        }
        return decodes;
    }

    pub fn streamEncode(self: *PAdicTokenizer, reader: anytype, allocator: Allocator) ![]u32 {
        var list = std.ArrayList(u32).init(allocator);
        errdefer list.deinit();
        var buf: [4096]u8 = undefined;
        while (true) {
            const read = try reader.read(buf[0..]);
            if (read == 0) break;
            var i: usize = 0;
            while (i < read) : (i += 1) {
                const ord = @as(u32, @intCast(buf[i]));
                try list.append(self.padicEncode(ord));
            }
        }
        return list.toOwnedSlice();
    }

    pub fn streamDecode(self: *PAdicTokenizer, tokens: []const u32, allocator: Allocator) ![]u8 {
        _ = self;
        var chars = try allocator.alloc(u8, tokens.len);
        errdefer allocator.free(chars);
        for (tokens, 0..) |tok, i| {
            chars[i] = @as(u8, @truncate(self.padicDecode(tok)));
        }
        return chars;
    }
};

test "PAdic Encode" {
    const GPA = std.heap.GeneralPurposeAllocator;
    var gpa = GPA(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();
    const vocab_tokens = [_][]const u8{ "a", "b", "c" };
    var vocab = Vocab.init(vocab_tokens[0..]);
    var tokenizer = try PAdicTokenizer.init(alloc, vocab, 5, 3);
    defer tokenizer.deinit();
    const encoded = try tokenizer.encode("abc");
    defer alloc.free(encoded);
    try std.testing.expectEqual(@as(usize, 3), encoded.len);
    try std.testing.expect(encoded[0] != 0);
    try std.testing.expect(encoded[1] != 0);
    try std.testing.expect(encoded[2] != 0);
}

